CREATE TABLE IF NOT EXISTS vans (plate VARCHAR(30) PRIMARY KEY, model VARCHAR(120) NOT NULL, seats INT NOT NULL, van_type VARCHAR(20) NOT NULL, daily_rate DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Available');
CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, contact VARCHAR(40), email VARCHAR(120), address VARCHAR(255), id_type VARCHAR(60), id_number VARCHAR(100));
CREATE TABLE IF NOT EXISTS rentals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL, plate VARCHAR(30) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days INT NOT NULL, daily_rate DECIMAL(10,2) NOT NULL, fee DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Active', return_date DATE, late_fee DECIMAL(10,2) NOT NULL DEFAULT 0, staff VARCHAR(100) NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(plate) REFERENCES vans(plate));
CREATE TABLE IF NOT EXISTS maintenance (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plate VARCHAR(30) NOT NULL, details VARCHAR(255), service_date DATE NOT NULL, staff VARCHAR(100), status VARCHAR(20) NOT NULL DEFAULT 'Open');
